const items = $input.all();
const data = items[0].json;
const qp = data.formQueryParameters || {};
const instancia = (qp.instancia || '').trim();
const whatsapp = (qp.whatsapp || '').trim();

const serie = (data['Série'] || '').trim();
const disciplina = (data['Disciplina'] || '').trim();
const tema = (data['Tema'] || '').trim();
const descricao = (data['Descrição da aula'] || '').trim();

if (!instancia || !whatsapp) {
  throw new Error('Parâmetros de retorno (instancia/whatsapp) ausentes — acesse o formulário pelo link enviado no WhatsApp.');
}
if (!serie || !disciplina || !tema) {
  throw new Error('Campos obrigatórios não preenchidos: série, disciplina e tema.');
}

const semanaForm = (data['semana'] || '').trim();
let semana;
if (semanaForm) {
  semana = semanaForm;
} else {
  const agora = new Date();
  const dia = agora.getDay();
  const diffSeg = dia === 0 ? -6 : 1 - dia;
  const segunda = new Date(agora); segunda.setDate(agora.getDate() + diffSeg);
  const sexta = new Date(segunda); sexta.setDate(segunda.getDate() + 4);
  const fmt = d => `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}`;
  semana = `${fmt(segunda)} a ${fmt(sexta)}`;
}

const query_rag = [disciplina, tema, serie].filter(Boolean).join(' ');

// Consolida arquivos de todos os itens (múltiplos uploads geram múltiplos itens no n8n)
const campoArquivo = 'Material de apoio (opcional)';
const arquivos = items
  .map(it => it.json[campoArquivo])
  .filter(a => a !== null && a !== undefined);

let arquivoRaw = null;
if (arquivos.length === 1) {
  arquivoRaw = arquivos[0];
} else if (arquivos.length > 1) {
  arquivoRaw = arquivos; // passa como array para os nós seguintes
}

return { json: { serie, disciplina, tema, descricao, semana, instancia, remoteJid: whatsapp, query_rag, timestamp: new Date().toISOString(), arquivo_upload_raw: arquivoRaw } };

const params = $('✅ Validar Inputs').first().json;
let prof = {};
try { prof = $input.first().json || {}; } catch(e) { prof = {}; }
const professor_nome = String(prof.nome || prof.Nome || 'Professor(a)').trim() || 'Professor(a)';
return { json: { ...params, professor_nome } };

