const params = $input.first().json;
const arquivoRaw = params.arquivo_upload_raw;

let temArquivo = false;
if (arquivoRaw !== null && arquivoRaw !== undefined) {
  temArquivo = true;
}

return [{ json: { ...params, tem_arquivo: temArquivo } }];

// Valida a extensão/tipo do arquivo enviado pelo professor
// Suporta múltiplos arquivos — valida o primeiro da lista

const params = $input.first().json;

let nomeArquivo = '';
let mimeType = '';

const raw = params.arquivo_upload_raw;

// Suporte a múltiplos arquivos (array) ou arquivo único (objeto)
const primeiroArquivo = Array.isArray(raw) ? raw[0] : raw;

if (typeof primeiroArquivo === 'object' && primeiroArquivo !== null) {
  nomeArquivo = primeiroArquivo.fileName || primeiroArquivo.filename || primeiroArquivo.name || primeiroArquivo.originalFilename || '';
  mimeType = primeiroArquivo.mimeType || primeiroArquivo.type || primeiroArquivo.mimetype || '';
} else if (typeof primeiroArquivo === 'string') {
  nomeArquivo = primeiroArquivo;
}

const extensaoMatch = nomeArquivo.match(/\.([^.]+)$/i);
const extensao = extensaoMatch ? extensaoMatch[1].toLowerCase() : '';

const extensoesPermitidas = ['pdf', 'docx', 'jpeg', 'jpg'];
const mimesPermitidos = [
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'image/jpeg'
];

const extensaoValida = extensoesPermitidas.includes(extensao);
const mimeValido = mimeType === '' || mimesPermitidos.some(m => mimeType.includes(m));

if (!extensaoValida) {
  return [{ json: {
    ...params,
    arquivo_valido: false,
    arquivo_erro: `❌ Formato não suportado (${extensao || 'desconhecido'}). Envie PDF, DOCX ou JPEG.`,
    arquivo_nome: nomeArquivo,
    arquivo_tipo: extensao
  }}];
}

return [{ json: {
  ...params,
  arquivo_valido: true,
  arquivo_nome: nomeArquivo,
  arquivo_tipo: extensao,
  arquivo_mime: mimeType
}}];

// Lê TODOS os binários do Form Trigger e classifica por tipo
// Suporta múltiplos arquivos: PDF, DOCX, JPEG, JPG

const params = $input.first().json;

let binaryData = {};
try {
  binaryData = $('📝 Form Plano de Aula').first().binary || {};
} catch(e) {
  binaryData = {};
}

const chaves = Object.keys(binaryData);

if (chaves.length === 0) {
  return [{
    json: {
      ...params,
      binary_keys: [],
      binary_key: '',
      pdf_keys: [],
      docx_keys: [],
      imagem_keys: [],
      texto_imagens: '',
      aviso_extracao: '',
      texto_extraido_raw: ''
    }
  }];
}

// Classifica cada binário por tipo
const pdfKeys = [];
const docxKeys = [];
const imagemKeys = [];
const textosImagem = [];

for (const chave of chaves) {
  const bin = binaryData[chave];
  const ext = (bin.fileExtension || (bin.fileName || '').split('.').pop() || '').toLowerCase();

  if (ext === 'pdf') {
    pdfKeys.push(chave);
  } else if (ext === 'docx') {
    docxKeys.push(chave);
  } else if (['jpeg', 'jpg'].includes(ext)) {
    imagemKeys.push(chave);
    textosImagem.push(`[Arquivo de imagem: ${bin.fileName || chave} — conteúdo visual enviado pelo professor. Utilize as informações de disciplina, série e tema como contexto principal.]`);
  }
}

// Chave principal para extração (primeiro PDF ou DOCX disponível)
const precisamExtracao = [...pdfKeys, ...docxKeys];
const primaryKey = precisamExtracao[0] || '';

// Tipo do arquivo principal (para o Extract from File)
const primaryBin = primaryKey ? binaryData[primaryKey] : null;
const primaryExt = primaryBin ? (primaryBin.fileExtension || (primaryBin.fileName || '').split('.').pop() || '').toLowerCase() : '';

return [{
  json: {
    ...params,
    binary_keys: chaves,
    binary_key: primaryKey,
    arquivo_tipo_extracao: primaryExt,
    pdf_keys: pdfKeys,
    docx_keys: docxKeys,
    imagem_keys: imagemKeys,
    texto_imagens: textosImagem.join('\n\n'),
    aviso_extracao: precisamExtracao.length > 0 ? 'REQUER_EXTRACAO' : '',
    texto_extraido_raw: textosImagem.join('\n\n')
  },
  binary: binaryData
}];

// Caminho só-imagem: texto contextual já foi montado no Ler Binário
const params = $input.first().json;
return [{
  json: {
    ...params,
    texto_do_arquivo: params.texto_imagens || '[Imagem enviada pelo professor.]'
  },
  binary: $('📝 Form Plano de Aula').first().binary || {}
}];

// Recebe o texto extraído (PDF ou DOCX) e limpa para envio ao agente
// Também incorpora textos de imagens se houver arquivos mistos

const params = $('✅ Validar Extensão').first().json;
const lerBinario = $('📄 Ler Binário').first().json;
const nomeArquivo = params.arquivo_nome || 'material_professor';
const tipoArquivo = params.arquivo_tipo || '';

let textoRaw = '';
try {
  const extrInput = $input.first();
  textoRaw = extrInput.json?.text || extrInput.json?.content || extrInput.json?.data || '';
  if (!textoRaw && extrInput.json) {
    const vals = Object.values(extrInput.json).filter(v => typeof v === 'string' && v.length > 50);
    if (vals.length > 0) textoRaw = vals[0];
  }
} catch(e) {
  textoRaw = '';
}

// Adiciona textos de imagens (caso haja arquivos mistos)
const textosImagem = lerBinario.texto_imagens || '';
if (textosImagem) {
  textoRaw = textoRaw ? textoRaw + '\n\n' + textosImagem : textosImagem;
}

function limparTexto(texto) {
  if (!texto) return '';
  texto = texto.replace(/[ \t]{2,}/g, ' ');
  texto = texto.replace(/(\n\s*){3,}/g, '\n\n');
  texto = texto.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '');
  texto = texto.replace(/\f/g, '\n---\n');
  return texto.trim();
}

const LIMITE_CHARS = 12000;
let textoLimpo = limparTexto(textoRaw);
let avisoCorte = '';

if (textoLimpo.length > LIMITE_CHARS) {
  textoLimpo = textoLimpo.substring(0, LIMITE_CHARS);
  const ultimoParag = textoLimpo.lastIndexOf('\n\n');
  if (ultimoParag > LIMITE_CHARS * 0.7) {
    textoLimpo = textoLimpo.substring(0, ultimoParag);
  }
  avisoCorte = '\n\n[ATENÇÃO: o material enviado excedeu o limite de contexto e foi parcialmente incluído.]';
}

const tipoLabel = {
  'pdf': 'PDF', 'docx': 'DOCX (Word)',
  'jpeg': 'Imagem JPEG', 'jpg': 'Imagem JPEG'
}[tipoArquivo] || tipoArquivo.toUpperCase();

const totalArquivos = lerBinario.binary_keys?.length || 1;
const avisoMultiplos = totalArquivos > 1 ? `\n(Total de arquivos enviados: ${totalArquivos} — conteúdo do primeiro arquivo de texto extraído)` : '';

const material_professor_contexto = textoLimpo
  ? `=== MATERIAL FORNECIDO PELO PROFESSOR ===\n\nNome do arquivo: ${nomeArquivo}${avisoMultiplos}\n\nTipo: ${tipoLabel}\n\nConteúdo extraído:\n\n${textoLimpo}${avisoCorte}\n\n=== FIM DO MATERIAL FORNECIDO PELO PROFESSOR ===`
  : `=== MATERIAL FORNECIDO PELO PROFESSOR ===\n\nNome do arquivo: ${nomeArquivo}\nTipo: ${tipoLabel}\n\n[Não foi possível extrair texto deste arquivo.]\n\n=== FIM DO MATERIAL FORNECIDO PELO PROFESSOR ===`;

return [{ json: {
  ...params,
  material_professor_contexto,
  arquivo_processado: true
}}];

// Caminho só-imagem chegando aqui diretamente
const params = $('✅ Validar Extensão').first().json;
const lerBinario = $('📄 Ler Binário').first().json;
const nomeArquivo = params.arquivo_nome || 'material_professor';

const textosImagem = lerBinario.texto_imagens || $input.first().json.texto_do_arquivo || '[Imagem enviada pelo professor.]';

const tipoLabel = 'Imagem JPEG';
const totalArquivos = lerBinario.binary_keys?.length || 1;
const avisoMultiplos = totalArquivos > 1 ? `\n(Total de arquivos enviados: ${totalArquivos})` : '';

const material_professor_contexto = `=== MATERIAL FORNECIDO PELO PROFESSOR ===\n\nNome do arquivo: ${nomeArquivo}${avisoMultiplos}\n\nTipo: ${tipoLabel}\n\n${textosImagem}\n\n=== FIM DO MATERIAL FORNECIDO PELO PROFESSOR ===`;

return [{ json: {
  ...params,
  material_professor_contexto,
  arquivo_processado: true
}}];

const params = $input.first().json;
return [{ json: {
  ...params,
  material_professor_contexto: 'Nenhum material adicional foi enviado pelo professor.',
  arquivo_processado: false
}}];

const embResp = $input.first().json;
const params = $('🔗 Juntar Contextos').first().json;

const embedding = embResp?.data?.[0]?.embedding;
if (!embedding) throw new Error('Embedding não gerado — verificar credencial OpenAI');

function stripAccents(s) {
  return (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function normalizarSerie(raw) {
  const norm = stripAccents(raw).toLowerCase();
  const ehMedio = /\b(medio|ensino medio|ensino med|\bem\b|2[°º]?\s grau|segundo\s grau|serie)\b/i.test(norm);
  const mapaSerieFundamental = {
    '1 ano': '1º ano', '2 ano': '2º ano', '3 ano': '3º ano',
    '4 ano': '4º ano', '5 ano': '5º ano', '6 ano': '6º ano',
    '7 ano': '7º ano', '8 ano': '8º ano', '9 ano': '9º ano',
    '1º ano': '1º ano', '2º ano': '2º ano', '3º ano': '3º ano',
    '4º ano': '4º ano', '5º ano': '5º ano', '6º ano': '6º ano',
    '7º ano': '7º ano', '8º ano': '8º ano', '9º ano': '9º ano',
    '1° ano': '1º ano', '2° ano': '2º ano', '3° ano': '3º ano',
    '4° ano': '4º ano', '5° ano': '5º ano', '6° ano': '6º ano',
    '7° ano': '7º ano', '8° ano': '8º ano', '9° ano': '9º ano',
    '1ºano': '1º ano', '2ºano': '2º ano', '3ºano': '3º ano',
    '4ºano': '4º ano', '5ºano': '5º ano', '6ºano': '6º ano',
    '7ºano': '7º ano', '8ºano': '8º ano', '9ºano': '9º ano',
    'primeiro ano': '1º ano', 'segundo ano': '2º ano', 'terceiro ano': '3º ano',
    'quarto ano': '4º ano', 'quinto ano': '5º ano', 'sexto ano': '6º ano',
    'setimo ano': '7º ano', 'oitavo ano': '8º ano', 'nono ano': '9º ano'
  };
  const mapaSerieMedio = {
    '1 serie': '1ª série', '1 ano': '1ª série',
    '2 serie': '2ª série', '2 ano': '2ª série',
    '3 serie': '3ª série', '3 ano': '3ª série',
    '1ª serie': '1ª série', '1ª série': '1ª série', '1º serie': '1ª série',
    '2ª serie': '2ª série', '2ª série': '2ª série', '2º serie': '2ª série',
    '3ª serie': '3ª série', '3ª série': '3ª série', '3º serie': '3ª série',
    '1° serie': '1ª série', '2° serie': '2ª série', '3° serie': '3ª série',
    'primeira serie': '1ª série', 'segunda serie': '2ª série', 'terceira serie': '3ª série'
  };
  const mapa = ehMedio ? mapaSerieMedio : mapaSerieFundamental;
  for (const key of Object.keys(mapa).sort((a, b) => b.length - a.length)) {
    if (new RegExp(`\\b${key.replace(/[°º]/g, '[°º]')}\\b`, 'i').test(norm)) {
      return mapa[key];
    }
  }
  const digitoMatch = norm.match(/[1-9]/);
  if (digitoMatch) {
    const n = digitoMatch[0];
    if (ehMedio && ['1','2','3'].includes(n)) {
      return n === '1' ? '1ª série' : n === '2' ? '2ª série' : '3ª série';
    }
    if (!ehMedio && parseInt(n) <= 9) return `${n}º ano`;
  }
  return raw;
}

function normalizarDisciplina(raw) {
  const mapaDisciplina = {
    'matematica': 'Matemática', 'matematicas': 'Matemática',
    'lingua portuguesa': 'Língua Portuguesa', 'portugues': 'Língua Portuguesa',
    'alfabetizacao': 'Língua Portuguesa', 'literatura': 'Língua Portuguesa',
    'redacao': 'Língua Portuguesa', 'leitura': 'Língua Portuguesa',
    'ciencias': 'Ciências', 'biologia': 'Biologia',
    'fisica': 'Física', 'quimica': 'Química',
    'historia': 'História', 'geografia': 'Geografia',
    'ingles': 'Inglês', 'lingua inglesa': 'Inglês',
    'arte': 'Arte', 'educacao fisica': 'Educação Física',
    'filosofia': 'Filosofia', 'sociologia': 'Sociologia'
  };
  const norm = stripAccents(raw).toLowerCase().trim();
  if (mapaDisciplina[norm]) return mapaDisciplina[norm];
  for (const k of Object.keys(mapaDisciplina).sort((a, b) => b.length - a.length)) {
    if (norm.includes(k)) return mapaDisciplina[k];
  }
  return raw;
}

const serieBusca = normalizarSerie(params.serie);
const disciplinaBusca = normalizarDisciplina(params.disciplina);

return [{
  json: {
    query_embedding: embedding,
    filtro_serie: serieBusca,
    filtro_componente: disciplinaBusca,
    limite_escopos: 3,
    limite_bncc: 3,
    serie: params.serie,
    disciplina: params.disciplina,
    tema: params.tema,
    semana: params.semana,
    professor_nome: params.professor_nome,
    instance: params.instancia,
    remoteJid: params.remoteJid,
    material_professor_contexto: params.material_professor_contexto || 'Nenhum material adicional foi enviado pelo professor.',
    descricao: params.descricao || ''
  }
}];

const resultados = $input.all().map(item => item.json);
const params = $('📦 Montar Payload Busca Dupla').first().json;

const safeVal = (v, fb = 'N/A') => {
  if (v === null || v === undefined) return fb;
  return String(v).trim() || fb;
};

if (!Array.isArray(resultados) || resultados.length === 0) {
  return [{
    json: {
      bncc_contexto: '',
      bncc_habilidades_texto: 'Habilidade não localizada — revisar base BNCC',
      bncc_unidade_tematica: '',
      bncc_objeto_conhecimento: params.tema,
      sem_resultado: true,
      material_professor_contexto: params.material_professor_contexto,
      ...params
    }
  }];
}

let habilidades = [];
let unidade_tematica = '';
let objeto_conhecimento = '';
let contexto_aula = [];

resultados.forEach(r => {
  if (r.fonte === 'bncc_oficial') {
    const codigo = safeVal(r.codigo, '');
    const conteudo = safeVal(r.conteudo, '');
    if (codigo && conteudo) {
      const hab = `(${codigo.replace(/[()]/g, '')}) ${conteudo}`;
      if (!habilidades.find(h => h.includes(codigo))) {
        habilidades.push(hab);
      }
    }
  } else {
    const conteudo = safeVal(r.conteudo, '');
    const titulo = safeVal(r.titulo, '');
    const unidadeMatch = conteudo.match(/\[UNIDADE\]\s*([^\n\[]+)/i);
    const aulaMatch = conteudo.match(/\[AULA\]\s*([^\n\[]+)/i);
    const habilidadesMatch = conteudo.match(/\[HABILIDADES\]\s*([\s\S]+?)(?=\[|$)/i);
    if (unidadeMatch && !unidade_tematica) unidade_tematica = unidadeMatch[1].trim();
    if (aulaMatch && !objeto_conhecimento) objeto_conhecimento = aulaMatch[1].trim();
    if (habilidadesMatch) {
      const habsRaw = habilidadesMatch[1].trim();
      habsRaw.split('\n').forEach(linha => {
        linha = linha.trim();
        if (linha.match(/^\(?[A-Z]{2}\d{2}[A-Z]{2,3}\d{2,3}[A-Z]?\)?/)) {
          if (!habilidades.find(h => h.includes(linha.substring(0, 12)))) {
            habilidades.push(linha);
          }
        }
      });
    }
    if (titulo) contexto_aula.push(`Tema da aula SEE-SP: ${titulo}`);
  }
});

const habilidades_texto = habilidades.length > 0
  ? habilidades.join('\n')
  : 'Habilidade não localizada — revisar base BNCC';

return [{
  json: {
    bncc_contexto: contexto_aula.join('\n'),
    bncc_habilidades_texto: habilidades_texto,
    bncc_unidade_tematica: unidade_tematica || params.tema,
    bncc_objeto_conhecimento: objeto_conhecimento || params.tema,
    sem_resultado: false,
    total_resultados: resultados.length,
    material_professor_contexto: params.material_professor_contexto,
    ...params
  }
}];
